package com.shop.billing;

public final class Money {
    private Money() {
    }

    public static long applyRate(long amountCents, int ratePercent) {
        return amountCents * ratePercent / 100;
    }
}

package com.shop.billing;

public final class InvoiceRegistry {
    public static final int TAX_POLICY_COUNT = 0;
}

package com.shop.billing.tax;

import com.shop.billing.Money;

public final class CnTaxPolicy {
    public long taxOf(long amountCents) {
        return amountCents * 6 / 100;
    }
}

